31	import org.springframework.samples.petclinic.model.Owner;
32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerHouseholdException;
35	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
36	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
37	import org.springframework.samples.petclinic.rest.api.OwnersApi;
38	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
39	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.PetDto;
41	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
44	import org.springframework.samples.petclinic.service.ClinicService;
45	import org.springframework.security.access.prepost.PreAuthorize;
46	import org.springframework.web.bind.annotation.CrossOrigin;
47	import org.springframework.web.bind.annotation.RequestMapping;
48	import org.springframework.web.bind.annotation.RestController;
49	import org.springframework.web.util.UriComponentsBuilder;
50	
51	import jakarta.transaction.Transactional;
52	
53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    private final ClinicService clinicService;
63	
64	    private final OwnerMapper ownerMapper;
65	
66	    private final PetMapper petMapper;
67	
68	    private final VisitMapper visitMapper;
69	
70	    public OwnerRestControllerV1(ClinicService clinicService,
71	                                 OwnerMapper ownerMapper,
72	                                 PetMapper petMapper,
73	                                 VisitMapper visitMapper) {
74	        this.clinicService = clinicService;
75	        this.ownerMapper = ownerMapper;
76	        this.petMapper = petMapper;
77	        this.visitMapper = visitMapper;
78	    }
79	
80	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
81	    @Override
82	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
83	        Collection<Owner> owners;
84	        if (lastName != null) {
85	            owners = this.clinicService.findOwnerByLastName(lastName);
86	        } else {
87	            owners = this.clinicService.findAllOwners();
88	        }
89	        if (owners.isEmpty()) {
90	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
91	        }
92	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
93	    }
94	
95	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
96	    @Override
97	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
98	        Owner owner = this.clinicService.findOwnerById(ownerId);
99	        if (owner == null) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
108	        List<String> missingFields = new ArrayList<>();
109	        if (isBlank(ownerFieldsDto.getFirstName())) {
110	            missingFields.add("firstName");
111	        }
112	        if (isBlank(ownerFieldsDto.getLastName())) {
113	            missingFields.add("lastName");
114	        }
115	        if (isBlank(ownerFieldsDto.getAddress())) {
116	            missingFields.add("address");
117	        }
118	        if (isBlank(ownerFieldsDto.getCity())) {
119	            missingFields.add("city");
120	        }
121	        if (isBlank(ownerFieldsDto.getTelephone())) {
122	            missingFields.add("telephone");
123	        }
124	        if (!missingFields.isEmpty()) {
125	            throw new InvalidOwnerFieldsException(missingFields);
126	        }
127	        // Normalize the telephone into E.164 form; a number that cannot form a valid
128	        // E.164 value is rejected with a 400.
129	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
130	        // Email is optional; when present it must be a syntactically valid address and is
131	        // stored lower-cased. An invalid address is rejected with a 400.
132	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
133	        // Reject the request if the E.164 telephone is already used by any other owner.
134	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
135	            .map(Owner::getTelephone)
136	            .filter(existing -> existing != null)
137	            .anyMatch(normalizedTelephone::equals);
138	        if (telephoneInUse) {
139	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
140	        }
141	        // Reject the request when another owner already shares this last name and address (compared
142	        // case-insensitively with collapsed whitespace), unless the caller explicitly opts in by
143	        // setting 'sharesHousehold' true.
144	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
145	            String normalizedLastName = collapse(ownerFieldsDto.getLastName());
146	            String normalizedAddress = collapse(ownerFieldsDto.getAddress());
147	            boolean householdInUse = this.clinicService.findAllOwners().stream()
148	                .anyMatch(existing -> collapse(existing.getLastName()).equals(normalizedLastName)
149	                    && collapse(existing.getAddress()).equals(normalizedAddress));
150	            if (householdInUse) {
151	                throw new DuplicateOwnerHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
152	            }
153	        }
154	        HttpHeaders headers = new HttpHeaders();
155	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
156	        owner.setTelephone(normalizedTelephone);
157	        owner.setEmail(normalizedEmail);
158	        // When no registration date is supplied, default it to the server's current date.
159	        if (owner.getRegistrationDate() == null) {
160	            owner.setRegistrationDate(LocalDate.now());
161	        }
162	        // Assign the customer code: '<LAST3>-<NNNN>' where LAST3 is the upper-cased first three
163	        // letters of the last name and NNNN is a global 4-digit zero-padded sequence equal to one
164	        // more than the current number of owners.
165	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
166	        this.clinicService.saveOwner(owner);
167	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
168	        headers.setLocation(UriComponentsBuilder.newInstance()
169	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
170	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
171	    }
172	
173	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
174	    @Override
175	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
176	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
177	        if (currentOwner == null) {
178	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
179	        }
180	        currentOwner.setAddress(ownerFieldsDto.getAddress());
181	        currentOwner.setCity(ownerFieldsDto.getCity());
182	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
183	        currentOwner.setLastName(ownerFieldsDto.getLastName());
184	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
185	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
186	        this.clinicService.saveOwner(currentOwner);
187	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
188	    }
189	
190	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
191	    @Transactional
192	    @Override
193	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
194	        Owner owner = this.clinicService.findOwnerById(ownerId);
195	        if (owner == null) {
196	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
197	        }
198	        this.clinicService.deleteOwner(owner);
199	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
200	    }
201	
202	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
203	    @Override
204	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
205	        Owner owner = this.clinicService.findOwnerById(ownerId);
206	        if (owner == null) {
207	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
208	        }
209	        HttpHeaders headers = new HttpHeaders();
210	        Pet pet = petMapper.toPet(petFieldsDto);
211	        owner.setId(ownerId);
212	        pet.setOwner(owner);
213	        pet.getType().setName(null);
214	        this.clinicService.savePet(pet);
215	        PetDto petDto = petMapper.toPetDto(pet);
216	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
217	            .buildAndExpand(pet.getId()).toUri());
218	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
219	    }
220	
221	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
222	    @Override
223	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
224	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
225	        if (currentOwner != null) {
226	            Pet currentPet = this.clinicService.findPetById(petId);
227	            if (currentPet != null) {
228	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
229	                currentPet.setName(petFieldsDto.getName());
230	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
231	                this.clinicService.savePet(currentPet);
232	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
233	            }
234	        }
235	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
236	    }
237	
238	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
239	    @Override
240	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
241	        HttpHeaders headers = new HttpHeaders();
242	        Visit visit = visitMapper.toVisit(visitFieldsDto);
243	        Pet pet = new Pet();
244	        pet.setId(petId);
245	        visit.setPet(pet);
246	        this.clinicService.saveVisit(visit);
247	        VisitDto visitDto = visitMapper.toVisitDto(visit);
248	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
249	            .buildAndExpand(visit.getId()).toUri());
250	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
251	    }
252	
253	
254	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
255	    @Override
256	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
257	        Owner owner = this.clinicService.findOwnerById(ownerId);
258	        if (owner != null) {
259	            Pet pet = owner.getPet(petId);
260	            if (pet != null) {
261	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
262	            }
263	        }
264	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
265	    }
266	
267	    private static boolean isBlank(String value) {
268	        return value == null || value.trim().isEmpty();
269	    }
270	
271	    /**
272	     * Normalize an owner identity field for household-duplicate comparison: trim, collapse every
273	     * run of whitespace to a single space, and lower-case. Used so that last name and address are
274	     * compared case-insensitively with collapsed whitespace.
275	     */
276	    private static String collapse(String value) {
277	        if (value == null) {
278	            return "";
279	        }
280	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
281	    }
282	
283	    /**
284	     * Build the customer code for a new owner: {@code '<LAST3>-<NNNN>'} where LAST3 is the
285	     * upper-cased first three letters of the last name and NNNN is a global 4-digit zero-padded
286	     * sequence equal to one more than the current number of owners (e.g. {@code 'SMI-0007'}).
287	     */
288	    private String nextCustomerCode(String lastName) {
289	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
290	        long sequence = this.clinicService.findAllOwners().size() + 1L;
291	        return String.format("%s-%04d", last3, sequence);
292	    }
293	
294	    /**
295	     * Convert a raw telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
296	     * {@code '+'} with its country code is preserved; otherwise the Australian country code
297	     * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national digits.
298	     * The result must be a {@code '+'} followed by 8 to 15 digits, otherwise an
299	     * {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a 400.
300	     */
301	    private static String toE164(String raw) {
302	        String cleaned = raw.trim().replaceAll("[\\s()\\-]", "");
303	        boolean hasCountryCode = cleaned.startsWith("+");
304	        String digits = hasCountryCode ? cleaned.substring(1) : cleaned;
305	        if (!digits.matches("\\d+")) {
306	            throw new InvalidOwnerFieldsException(List.of("telephone"));
307	        }
308	        if (!hasCountryCode) {
309	            if (digits.startsWith("0")) {
310	                digits = digits.substring(1);
311	            }
312	            digits = "61" + digits;
313	        }
314	        if (digits.length() < 8 || digits.length() > 15) {
315	            throw new InvalidOwnerFieldsException(List.of("telephone"));
316	        }
317	        return "+" + digits;
318	    }
319	
320	    /**
321	     * Pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
322	     * and a domain with at least one dot-separated label, none of which contain whitespace or
323	     * a second {@code @}. This is deliberately permissive but rejects obviously malformed input.
324	     */
325	    private static final Pattern EMAIL_PATTERN =
326	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
327	
328	    /**
329	     * Validate and normalize an optional owner email. Returns {@code null} when no email was
330	     * supplied (the field is optional). When supplied it must be a syntactically valid address,
331	     * otherwise an {@link InvalidOwnerFieldsException} is thrown so the request is rejected with a
332	     * 400. A valid address is returned lower-cased.
333	     */
334	    private static String normalizeEmail(String email) {
335	        if (email == null || email.isEmpty()) {
336	            return null;
337	        }
338	        String trimmed = email.trim();
339	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
340	            throw new InvalidOwnerFieldsException(List.of("email"));
341	        }
342	        return trimmed.toLowerCase();
343	    }
344	}
